const labels = ["FIBFIB-SPEC.fibfib-loop","FIBFIB-SPEC.fibfib-correct"];
const ps = labels.map(label => tools.exec_command({
  cmd:`timeout 90s kprove spec.k --definition verification-kompiled --spec-module FIBFIB-SPEC --claims ${label}`,
  workdir:"/work",yield_time_ms:1000,max_output_tokens:30000
}));
const rs=await Promise.all(ps);
for(let i=0;i<rs.length;i++) text(`${labels[i]} exit=${rs[i].exit_code}\n${rs[i].output}`);

const results = await Promise.all([
  tools.exec_command({cmd:"python3 py2mpy.py solution.py > solution.mpy && cmp -s solution.py <(python3 - <<'PY'\nprint('')\nPY\n) || true; sed -n '1,180p' solution.mpy",workdir:"/work",yield_time_ms:10000,max_output_tokens:12000}),
  tools.exec_command({cmd:"krun smoke.mpy --definition runtime-kompiled --output none",workdir:"/work",yield_time_ms:10000,max_output_tokens:12000})
]);
text(`translate exit=${results[0].exit_code}\n${results[0].output}`);
text(`krun exit=${results[1].exit_code}\n${results[1].output}`);
